styles:
.b-tariffs {
    container-type: inline-size;
    --tariffs-gap: 1.5em;
}

.b-tariffs__title {
    margin: 0 0 1em;
}

/* A flex or grid box outranks the browser's own [hidden] rule. */
.b-tariffs__nav[hidden],
.b-tariffs__item[hidden] {
    display: none;
}

/* The grid, and what the slider starts from. Up to `--tariffs-columns` across, fewer when a column
   would be narrower than 16em; on a narrow screen, a stack. */
.b-tariffs__track {
    display: grid;
    grid-template-columns: repeat(
        auto-fill,
        minmax(min(100%, max(16em, (100% - (var(--tariffs-columns, 3) - 1) * var(--tariffs-gap)) / var(--tariffs-columns, 3))), 1fr)
    );
    gap: var(--tariffs-gap);
    margin: 0;
    padding: 0;
    list-style: none;
}

/* No margin of its own: a theme's prose spaces `li + li`, which in a grid lifts the first cell
   above its row. */
.b-tariffs__item {
    min-width: 0;
    margin: 0;
}

/* Every card as tall as the row, the button pressed to the bottom: prices are compared side by side. */
.b-tariffs__card {
    display: flex;
    flex-direction: column;
    gap: 0.75em;
    box-sizing: border-box;
    height: 100%;
    margin: 0;
    padding: 1.5em;
    border: 1px solid color-mix(in srgb, currentColor 18%, transparent);
    border-radius: 0.75em;
}

.b-tariffs__card.is-featured {
    border: 2px solid currentColor;
}

.b-tariffs__featured {
    align-self: flex-start;
    margin: 0;
    padding: 0.2em 0.7em;
    font-size: 0.8em;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.04em;
    border-radius: 999px;
    background: color-mix(in srgb, currentColor 12%, transparent);
}

.b-tariffs__badge {
    margin: 0;
    font-size: 0.85em;
    font-weight: 600;
    letter-spacing: 0.04em;
    opacity: 0.7;
}

.b-tariffs__name {
    margin: 0;
    font-size: 1.35em;
}

.b-tariffs__price {
    display: flex;
    flex-wrap: wrap;
    align-items: baseline;
    gap: 0.25em;
    margin: 0;
}

.b-tariffs__amount {
    font-size: 2em;
    font-weight: 700;
    line-height: 1.1;
}

.b-tariffs__period {
    opacity: 0.7;
}

.b-tariffs__includes {
    margin: 0.5em 0 0;
    font-weight: 600;
}

/* A tick drawn by CSS; two columns once the list is longer than four lines. */
.b-tariffs__features {
    margin: 0;
    padding: 0;
    list-style: none;
    column-gap: 1.5em;
}

.b-tariffs__features.is-long {
    columns: 2;
}

.b-tariffs__features li {
    position: relative;
    padding-inline-start: 1.5em;
    margin: 0 0 0.4em;
    break-inside: avoid;
}

.b-tariffs__features li::before {
    content: '';
    position: absolute;
    inset-inline-start: 0.2em;
    top: 0.3em;
    width: 0.35em;
    height: 0.7em;
    border: solid currentColor;
    border-width: 0 0.15em 0.15em 0;
    transform: rotate(45deg);
}

@container (max-width: 30em) {
    .b-tariffs__features.is-long {
        columns: 1;
    }
}

.b-tariffs__text {
    margin: 0;
    opacity: 0.85;
}

.b-tariffs__services {
    display: flex;
    flex-wrap: wrap;
    gap: 0.35em 0.75em;
    margin: 0;
    padding: 0;
    list-style: none;
    font-size: 0.9em;
}

/* No margin of their own: a theme's prose spaces `li + li`, which in a row lifts the first item
   above the others. */
.b-tariffs__services li {
    margin: 0;
}

.b-tariffs__services a {
    color: inherit;
}

.b-tariffs__button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    margin-top: auto;
    padding: 0.75em 1.5em;
    font-weight: 600;
    text-align: center;
    text-decoration: none;
    text-transform: uppercase;
    letter-spacing: 0.04em;
    color: inherit;
    border: 2px solid currentColor;
    border-radius: 999px;
}

.b-tariffs__button--primary {
    color: Canvas;
    background: CanvasText;
    border-color: CanvasText;
}

.b-tariffs__button--link {
    padding-inline: 0;
    border-color: transparent;
    text-decoration: underline;
}

/* A slider is a ribbon that scrolls sideways — without the script, too. One card on a phone,
   `--tariffs-columns` across on a wider screen. */
.b-tariffs[data-tariffs-layout='slider'] .b-tariffs__viewport {
    overflow-x: auto;
    scrollbar-width: thin;
    scroll-snap-type: x mandatory;
}

.b-tariffs[data-tariffs-layout='slider'] .b-tariffs__track {
    display: flex;
}

.b-tariffs[data-tariffs-layout='slider'] .b-tariffs__item {
    flex: 0 0 calc((100% - (var(--tariffs-columns, 3) - 1) * var(--tariffs-gap)) / var(--tariffs-columns, 3));
    scroll-snap-align: start;
}

@container (max-width: 48em) {
    .b-tariffs[data-tariffs-layout='slider'] .b-tariffs__item {
        flex-basis: calc((100% - var(--tariffs-gap)) / 2);
    }
}

@container (max-width: 32em) {
    .b-tariffs[data-tariffs-layout='slider'] .b-tariffs__item {
        flex-basis: 100%;
    }
}

.b-tariffs__nav {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: 0.5em;
    margin-top: 1em;
}

.b-tariffs__count {
    margin: 0 auto 0 0;
    font-variant-numeric: tabular-nums;
}

.b-tariffs__arrow {
    width: 2.5em;
    height: 2.5em;
    font: inherit;
    color: inherit;
    background: none;
    border: 1px solid currentColor;
    border-radius: 50%;
    cursor: pointer;
}

.b-tariffs__arrow:disabled {
    opacity: 0.35;
    cursor: default;
}

script:
const layout = el.dataset.tariffsLayout || 'slider'
const viewport = el.querySelector('.b-tariffs__viewport')
const track = el.querySelector('.b-tariffs__track')
const nav = el.querySelector('.b-tariffs__nav')
const still = window.matchMedia('(prefers-reduced-motion: reduce)')
const items = () => Array.from(el.querySelectorAll('.b-tariffs__item'))

if (layout === 'slider' && viewport && track && nav) {
  const arrows = Array.from(nav.querySelectorAll('.b-tariffs__arrow'))
  const current = nav.querySelector('[data-tariffs-current]')
  const total = nav.querySelector('[data-tariffs-total]')
  const pad = (n) => (n < 10 ? '0' + n : String(n))

  // One card further, measured rather than assumed: the number across changes with the width.
  const step = () => {
    const first = items()[0]
    const gap = parseFloat(getComputedStyle(track).columnGap) || 0
    return first ? first.getBoundingClientRect().width + gap : viewport.clientWidth
  }
  const atEnd = () => viewport.scrollLeft + viewport.clientWidth >= viewport.scrollWidth - 2
  const go = (direction) => {
    viewport.scrollBy({ left: direction * step(), behavior: still.matches ? 'auto' : 'smooth' })
  }

  // Printed hidden, so that without this script there is no "01 / 01" and no arrows that do
  // nothing. Hidden again while every card fits: then there is nothing to scroll to.
  const update = () => {
    const count = items().length
    const fits = viewport.scrollWidth <= viewport.clientWidth + 2
    nav.hidden = count < 2 || fits
    if (nav.hidden) return

    // The number of the first card in view, and how many there are.
    const first = Math.min(count, Math.round(viewport.scrollLeft / step()) + 1)
    if (current) current.textContent = pad(first)
    if (total) total.textContent = pad(count)

    for (const arrow of arrows) {
      arrow.disabled = Number(arrow.dataset.tariffsStep) < 0 ? viewport.scrollLeft <= 1 : atEnd()
    }
  }

  for (const arrow of arrows) {
    arrow.addEventListener('click', () => go(Number(arrow.dataset.tariffsStep) || 1))
  }
  viewport.addEventListener('scroll', update, { passive: true })
  if ('ResizeObserver' in window) new ResizeObserver(update).observe(viewport)
  update()
}
